def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify if there is a strong bidder (likely Bob from trace)
    strong_pressure = highest_prev_bid >= DAILY_SALARY * 0.85  # ~59.5

    # Supply-aware aggressiveness: higher supply reduces need to overbid
    # (We only use it to slightly scale bids.)
    supply_clamped = max(MIN_SUPPLY, min(MAX_SUPPLY, float(supply)))
    supply_scale = (supply_clamped - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1

    # Base strategy
    if strong_pressure:
        # Compete but don't chase the very top; aim to be near the leader's level minus a margin.
        # If our HP is low, we must secure water.
        if hp <= 2:
            target = highest_prev_bid * 0.95
        elif hp <= 4:
            target = max(highest_prev_bid * 0.75, DAILY_SALARY * 0.55)
        else:
            target = max(highest_prev_bid * 0.65, DAILY_SALARY * 0.45)
    else:
        # If no one is bidding aggressively (e.g., like David), bid enough to stay ahead.
        if hp <= 2:
            target = DAILY_SALARY * 0.85
        elif hp <= 4:
            target = DAILY_SALARY * 0.65
        else:
            target = max(DAILY_SALARY * 0.5, highest_prev_bid + 5.0)

    # Adjust for supply: at higher supply, bid slightly less; at lower supply, bid slightly more.
    # supply_scale=1 => high supply => reduce; supply_scale=0 => low supply => increase
    target *= (1.0 - 0.15 * supply_scale)

    # Ensure within budget and non-negative
    bid = max(0.0, min(float(budget), float(target)))

    # If budget is tiny, still bid something (game may require positive to win water)
    if bid == 0.0 and budget > 0:
        bid = min(budget, 1.0)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.28
        if hp <= 2 or no_water >= 1:
            safe_bid = DAILY_SALARY * 0.55
        return float(min(budget, safe_bid))

    prev_bids = []
    prev_valid = []
    david_like_bid = None
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
            prev_bids.append(bid)
            prev_valid.append((opp, bid))
            req = opp.get('water_requirement', WATER_REQ)
            sal = opp.get('daily_salary', DAILY_SALARY)
            if req == 9 and sal == 90 and opp.get('budget', 0) > 200:
                if david_like_bid is None or bid < david_like_bid:
                    david_like_bid = bid

    if david_like_bid is None:
        for opp, bid in prev_valid:
            if opp.get('budget', 0) > 200 and bid <= 40:
                if david_like_bid is None or bid < david_like_bid:
                    david_like_bid = bid

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_count = len(alive_opponents) + 1
    units = max(1, int(supply // WATER_REQ))
    scarcity = units < active_count
    very_tight = units <= 1

    base = DAILY_SALARY * 0.22
    if supply >= 22:
        base = DAILY_SALARY * 0.18
    elif supply <= 17:
        base = DAILY_SALARY * 0.34

    if scarcity:
        if david_like_bid is not None:
            target = david_like_bid + 1.2
        else:
            target = max(DAILY_SALARY * 0.36, highest_prev + 1.0)
    else:
        if david_like_bid is not None:
            target = max(base, david_like_bid - 3.0)
        else:
            target = base

    if very_tight:
        target = max(target, DAILY_SALARY * 0.38)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.82)
    elif hp <= 4 or no_water >= 1:
        target = max(target, DAILY_SALARY * 0.58)

    if budget < DAILY_SALARY * 2:
        target = min(target, budget)
    elif budget > 500 and scarcity and david_like_bid is not None:
        target = max(target, david_like_bid + 1.8)

    target = min(target, DAILY_SALARY * 0.92)
    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    TOTAL_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    highest_prev_bid = 0.0
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                highest_prev_bid = max(highest_prev_bid, prev['bid'])

    default_competitive_bid = MY_DAILY_SALARY * 0.3

    base_bid_to_win = max(highest_prev_bid + 1.0, default_competitive_bid)

    bid = 0.0
    current_day = day_context['day']
    days_left = TOTAL_DAYS - current_day

    if my_status['hp'] <= 2: 
        bid = MY_DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4: 
        bid = max(base_bid_to_win, MY_DAILY_SALARY * 0.7)
    elif my_status['hp'] >= 8 and highest_prev_bid > MY_DAILY_SALARY * 0.6: 
        bid = MY_DAILY_SALARY * 0.2
    elif current_day < TOTAL_DAYS / 2: 
        bid = max(base_bid_to_win, MY_DAILY_SALARY * 0.4)
    elif days_left <= 3: 
        bid = max(base_bid_to_win, MY_DAILY_SALARY * 0.6)
    else: 
        bid = base_bid_to_win

    final_bid = max(1.0, min(bid, my_status['budget']))

    return round(final_bid, 2)

