    prev_high = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_high = max(prev_high, prev['bid'])

    # Emergency if very thirsty or low hp
    if hp <= 2 or no_water_days >= 2:
        return min(budget, DAILY_SALARY * 0.9)

    # Normal strategy: adapt based on opponents' past aggression
    if prev_high >= 75:
        # Opponent is very aggressive, conserve budget
        base_bid = min(budget, DAILY_SALARY * 0.65)
    elif prev_high >= 60:
        base_bid = min(budget, DAILY_SALARY * 0.7)
    else:
        base_bid = min(budget, DAILY_SALARY * 0.5)

    # Increase bid slightly if supply is low (more competition)
    if supply < 18:
        base_bid = min(budget, base_bid * 1.1)

    return base_bid

